  "inlineSchema": "datasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  output        = \"../src/generated/client\"\n  binaryTargets = [\"native\", \"rhel-openssl-1.0.x\", \"rhel-openssl-3.0.x\", \"debian-openssl-3.0.x\"]\n}\n\nmodel AdminUser {\n  id           String   @id @default(cuid())\n  name         String\n  email        String   @unique\n  passwordHash String\n  role         String   @default(\"SUPER_ADMIN\") // SUPER_ADMIN, SUPPORT, BILLING\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n}\n\nmodel Customer {\n  id            String               @id @default(cuid())\n  name          String\n  email         String               @unique\n  passwordHash  String\n  companyName   String?\n  phone         String?\n  status        String               @default(\"ACTIVE\") // ACTIVE, SUSPENDED\n  internalNotes String?\n  subscriptions Subscription[]\n  licenses      License[]\n  tickets       SupportTicket[]\n  quotes        CustomizationQuote[]\n  createdAt     DateTime             @default(now())\n  updatedAt     DateTime             @updatedAt\n}\n\nmodel Plan {\n  id               String         @id @default(cuid())\n  tier             String         @unique // BASIC, GROW, PLUS\n  name             String\n  description      String\n  badge            String?\n  isActive         Boolean        @default(true)\n  entitlementsJson String // JSON of LicenseEntitlements\n  pricingTiers     PricingTier[]\n  subscriptions    Subscription[]\n  createdAt        DateTime       @default(now())\n  updatedAt        DateTime       @updatedAt\n}\n\nmodel PricingTier {\n  id              String   @id @default(cuid())\n  planId          String\n  plan            Plan     @relation(fields: [planId], references: [id], onDelete: Cascade)\n  duration        String // MONTHLY, SIX_MONTHS, YEARLY, TWO_YEARS\n  price           Float\n  originalPrice   Float?\n  discountPercent Float    @default(0)\n  isActive        Boolean  @default(true)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  @@unique([planId, duration])\n}\n\nmodel PlatformSetting {\n  id        String   @id @default(cuid())\n  key       String   @unique\n  value     String\n  updatedAt DateTime @updatedAt\n}\n\nmodel Promotion {\n  id              String    @id @default(cuid())\n  code            String    @unique\n  discountPercent Float\n  maxDiscount     Float?\n  validUntil      DateTime?\n  isActive        Boolean   @default(true)\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n}\n\nmodel Subscription {\n  id                 String   @id @default(cuid())\n  customerId         String\n  customer           Customer @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  planId             String\n  plan               Plan     @relation(fields: [planId], references: [id])\n  duration           String // MONTHLY, SIX_MONTHS, YEARLY, TWO_YEARS\n  status             String   @default(\"ACTIVE\") // ACTIVE, PAST_DUE, EXPIRED, CANCELLED, SUSPENDED\n  amount             Float\n  currency           String   @default(\"INR\")\n  startDate          DateTime @default(now())\n  endDate            DateTime\n  hasSetupAssistance Boolean  @default(false)\n  setupFee           Float    @default(0)\n  paymentStatus      String   @default(\"PAID\") // PAID, PENDING, FAILED\n  paymentReference   String?\n  license            License?\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n}\n\nmodel License {\n  id               String                 @id @default(cuid())\n  licenseKey       String                 @unique\n  customerId       String\n  customer         Customer               @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  subscriptionId   String                 @unique\n  subscription     Subscription           @relation(fields: [subscriptionId], references: [id], onDelete: Cascade)\n  planTier         String // BASIC, GROW, PLUS\n  boundDomain      String?\n  installationUuid String?\n  status           String                 @default(\"ACTIVE\") // ACTIVE, SUSPENDED, REVOKED, EXPIRED\n  activatedAt      DateTime?\n  expiresAt        DateTime\n  lastHeartbeatAt  DateTime?\n  validationLogs   LicenseValidationLog[]\n  createdAt        DateTime               @default(now())\n  updatedAt        DateTime               @updatedAt\n}\n\nmodel LicenseValidationLog {\n  id               String   @id @default(cuid())\n  licenseId        String\n  license          License  @relation(fields: [licenseId], references: [id], onDelete: Cascade)\n  licenseKey       String\n  domain           String?\n  installationUuid String?\n  storeVersion     String?\n  ipAddress        String?\n  outcome          String // SUCCESS, INVALID_DOMAIN, EXPIRED, REVOKED, NOT_FOUND\n  timestamp        DateTime @default(now())\n}\n\nmodel SoftwareRelease {\n  id               String   @id @default(cuid())\n  version          String   @unique\n  releaseDate      DateTime @default(now())\n  isLatest         Boolean  @default(false)\n  isSecurityUpdate Boolean  @default(false)\n  changelog        String\n  downloadUrl      String?\n  createdAt        DateTime @default(now())\n}\n\nmodel SupportTicket {\n  id            String          @id @default(cuid())\n  ticketNumber  String          @unique\n  customerId    String\n  customer      Customer        @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  subject       String\n  category      String\n  priority      String          @default(\"MEDIUM\") // LOW, MEDIUM, HIGH, URGENT\n  status        String          @default(\"OPEN\") // OPEN, IN_PROGRESS, RESOLVED, CLOSED\n  internalNotes String?\n  messages      TicketMessage[]\n  createdAt     DateTime        @default(now())\n  updatedAt     DateTime        @updatedAt\n}\n\nmodel TicketMessage {\n  id         String        @id @default(cuid())\n  ticketId   String\n  ticket     SupportTicket @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n  senderType String // CUSTOMER, ADMIN\n  senderName String\n  message    String\n  createdAt  DateTime      @default(now())\n}\n\nmodel CustomizationQuote {\n  id               String   @id @default(cuid())\n  customerId       String\n  customer         Customer @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  title            String\n  scopeDescription String\n  quotedAmount     Float\n  status           String   @default(\"SENT\") // DRAFT, SENT, ACCEPTED, REJECTED, PAID\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n}\n\nmodel CentralThemeItem {\n  id           String   @id @default(cuid())\n  themeCode    String   @unique\n  name         String\n  description  String\n  previewImage String?\n  isPremium    Boolean  @default(false)\n  price        Float    @default(0)\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n}\n\nmodel SystemBroadcast {\n  id         String    @id @default(cuid())\n  title      String\n  message    String\n  severity   String    @default(\"INFO\") // INFO, WARNING, CRITICAL\n  targetTier String    @default(\"ALL\") // ALL, BASIC, GROW, PLUS\n  isActive   Boolean   @default(true)\n  expiresAt  DateTime?\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n}\n\nmodel AdminAuditLog {\n  id         String   @id @default(cuid())\n  adminEmail String   @default(\"admin@technext.co\")\n  action     String // e.g. \"LICENSE_GENERATED\", \"VERSION_RELEASED\", \"QUOTE_ISSUED\"\n  target     String // e.g. \"License AVRO-PLUS-XXXX\", \"Customer Rajesh\"\n  details    String?\n  ipAddress  String?  @default(\"127.0.0.1\")\n  severity   String   @default(\"NORMAL\") // NORMAL, WARNING, CRITICAL\n  timestamp  DateTime @default(now())\n}\n",
